using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketClassifierController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;
    private readonly TicketModelTrainer _trainer;
    private static string[]? _cachedLabels;

    public TicketClassifierController(
        PredictionEnginePool<TicketData, TicketPrediction> predictionPool,
        TicketModelTrainer trainer)
    {
        _predictionPool = predictionPool;
        _trainer = trainer;
    }

    [HttpPost("predict")]
    public ActionResult<TicketPredictionResponse> Predict([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionPool.Predict(input);

        var labels = GetLabels();
        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
        {
            confidence[labels[i]] = prediction.Score[i];
        }

        return Ok(new TicketPredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        });
    }

    [HttpPost("train")]
    public ActionResult<string> Train()
    {
        var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "tickets.csv");
        var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        var metrics = _trainer.TrainAndSaveModel(dataPath, modelPath);
        _cachedLabels = null; // Reset cache after retraining
        return Ok(metrics);
    }

    private string[] GetLabels()
    {
        if (_cachedLabels is not null)
            return _cachedLabels;

        var modelPath = Path.Combine(AppContext.BaseDirectory, "Data", "model.zip");
        var mlContext = new MLContext();
        var model = mlContext.Model.Load(modelPath, out var schema);

        var labelColumn = schema["Category"];
        if (labelColumn.Type is VectorDataViewType vectorType)
        {
            var slotNames = new VBuffer<ReadOnlyMemory<char>>();
            labelColumn.GetSlotNames(ref slotNames);
            _cachedLabels = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
        }
        else
        {
            // Fallback: use the score column metadata from a dummy prediction
            _cachedLabels = ["Billing", "General", "Technical"];
        }

        return _cachedLabels;
    }
}

